/** 32-bit FNV-1a hash as 8 hex chars. Deterministic, no crypto module needed. */
function fnv1a(input, seed = 0x811c9dc5) {
  let hash = seed >>> 0;
  const str = String(input);
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

/**
 * Deterministic UUID-shaped id (Qdrant accepts UUID strings as point ids).
 * Not RFC-4122 random - it is a stable fingerprint so re-ingesting the same
 * chunk overwrites the same point instead of duplicating it.
 */
function stableUuid(input) {
  const h = [0x811c9dc5, 0x01000193, 0x9e3779b9, 0x85ebca6b].map((seed) => fnv1a(input, seed)).join('');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-5${h.slice(13, 16)}-a${h.slice(17, 20)}-${h.slice(20, 32)}`;
}

/** YYYY-MM-DD for a Date in the given IANA timezone. */
function isoDateInZone(date, timeZone) {
  return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}

/** True for a real calendar date in YYYY-MM-DD form (rejects 2026-02-30). */
function isValidIsoDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [y, m, d] = value.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}

// ---- src/shared/llm-response.js
// Read the text out of an LLM HTTP response, for either provider.
//
// Anthropic Messages API: content is an array of blocks. With adaptive
// thinking on, `thinking` blocks can come before the `text` block, and with
// server-side fallbacks a `fallback` block marks a model switch - so we never
// assume content[0] is the answer. stop_reason must be checked before the
// content is trusted.
//
// Ollama /api/chat (stream: false): { message: { content }, done_reason }.

/**
 * @returns {{ ok: true, text: string, provider: string, model: string|null, fellBack: boolean }
 *         | { ok: false, error: string, provider: string, retryable: boolean }}
 */
function readLlmText(response) {
  if (!response || typeof response !== 'object') {
    return { ok: false, provider: 'unknown', error: 'Empty response from LLM', retryable: true };
  }
  // n8n HTTP node with "continue" error handling puts failures under `error`.
  if (response.error && !response.content && !response.message) {
    const msg = typeof response.error === 'string' ? response.error : response.error.message || JSON.stringify(response.error);
    return { ok: false, provider: 'unknown', error: `LLM request failed: ${msg}`, retryable: true };
  }

  if (Array.isArray(response.content)) {
    const provider = 'anthropic';
    if (response.type === 'error') {
      return { ok: false, provider, error: `Anthropic error: ${response.error?.message || 'unknown'}`, retryable: false };
    }
    if (response.stop_reason === 'refusal') {
      const category = response.stop_details?.category || 'unspecified';
      return { ok: false, provider, error: `Claude declined the request (category: ${category})`, retryable: false };
    }
    if (response.stop_reason === 'max_tokens') {
      return { ok: false, provider, error: 'Claude hit max_tokens - output is incomplete. Raise maxOutputTokens in the Config node.', retryable: false };
    }
    const text = response.content
      .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
      .map((b) => b.text)
      .join('');
    if (!text.trim()) {
      return { ok: false, provider, error: 'Claude returned no text block', retryable: true };
    }
    const fellBack = response.content.some((b) => b && b.type === 'fallback');
    return { ok: true, provider, text, model: response.model || null, fellBack };
  }

  if (response.message && typeof response.message.content === 'string') {
    const provider = 'ollama';
    if (response.done_reason === 'length') {
      return { ok: false, provider, error: 'Ollama stopped at num_predict - output is incomplete', retryable: false };
    }
    const text = response.message.content;
    if (!text.trim()) return { ok: false, provider, error: 'Ollama returned an empty message', retryable: true };
    return { ok: true, provider, text, model: response.model || null, fellBack: false };
  }

  return { ok: false, provider: 'unknown', error: 'Unrecognised LLM response shape', retryable: false };
}

// ---- src/calendar/digest.js
// Digest writing: request builder for Claude or local Ollama, a deterministic
// fallback digest (used when the LLM is down or there is nothing on the
// calendar), and the final message composer.

const DIGEST_SYSTEM = `You write a short morning digest of a family's calendar.
Plain, warm language a 10-year-old and a grandparent can both read. No emojis, no markdown headings.
Structure: one opening line, then the day in time order (who, what, when, where), then anything that needs attention (overlaps, early starts, things to bring).
Maximum 180 words. Use only the events provided - do not invent plans, reminders or weather.`;

function eventLine(e, includePrivate) {
  const where = includePrivate && e.location ? ` @ ${e.location}` : '';
  const note = includePrivate && e.description ? ` - note: ${e.description}` : '';
  return `- ${e.timeLabel}: ${e.title} [${e.members.join(', ')}]${where}${note}`;
}

function dayPlanToText(day, { includePrivate = true } = {}) {
  const lines = [`Date: ${day.dateLabel} (${day.timezone})`, 'Events:'];
  lines.push(...(day.events.length ? day.events.map((e) => eventLine(e, includePrivate)) : ['- nothing scheduled']));
  if (day.conflicts.length) {
    lines.push('Overlaps:', ...day.conflicts.map((c) => `- ${c.first} overlaps ${c.second}`));
  }
  return lines.join('\n');
}

/**
 * @returns {{ route: 'claude'|'ollama'|'none', request?: object }}
 */
function buildDigestRequest(day, config = {}) {
  if (day.eventCount === 0) return { route: 'none' };
  const provider = config.llmProvider === 'ollama' ? 'ollama' : 'claude';
  // Locations and event notes stay local unless explicitly allowed.
  const includePrivate = provider === 'ollama' || config.sendLocationsToCloud === true;
  const prompt = `Family: ${config.familyName || 'our family'}\n${dayPlanToText(day, { includePrivate })}`;

  if (provider === 'ollama') {
    return {
      route: 'ollama',
      request: {
        model: config.ollamaModel || 'llama3.1:8b',
        stream: false,
        options: { temperature: 0.3, num_predict: 600 },
        messages: [
          { role: 'system', content: DIGEST_SYSTEM },
          { role: 'user', content: prompt },
        ],
      },
    };
  }
  const request = {
    model: config.anthropicModel || 'claude-opus-5',
    max_tokens: 2000,
    system: DIGEST_SYSTEM,
    output_config: { effort: 'low' },
    messages: [{ role: 'user', content: prompt }],
  };
  if (config.useServerFallbacks !== false) request.fallbacks = 'default';
  return { route: 'claude', request };
}

/** Deterministic digest - no AI involved. */
function renderPlainDigest(day) {
  if (day.eventCount === 0) return `Good morning! Nothing is on the family calendar for ${day.dateLabel}. Enjoy the free day.`;
  const lines = [`Good morning! Here is ${day.dateLabel}:`, ''];
  for (const e of day.events) lines.push(`${e.timeLabel} - ${e.title} (${e.members.join(', ')})${e.location ? `, ${e.location}` : ''}`);
  if (day.conflicts.length) {
    lines.push('', 'Heads up - these overlap:');
    for (const c of day.conflicts) lines.push(`${c.first} / ${c.second}`);
  }
  return lines.join('\n');
}

/**
 * @param {object|null} llmResponse  raw HTTP response (Claude or Ollama), or null when skipped
 */
function composeDigest(day, llmResponse, config = {}) {
  let body;
  let usedFallback = false;
  let fallbackReason = null;
  if (llmResponse) {
    const read = readLlmText(llmResponse);
    if (read.ok) body = read.text.trim();
    else {
      usedFallback = true;
      fallbackReason = read.error;
    }
  } else {
    usedFallback = true;
    fallbackReason = day.eventCount === 0 ? 'no events' : 'LLM skipped';
  }
  if (!body) body = renderPlainDigest(day);

  const footer = usedFallback && day.eventCount > 0 ? '\n\n(Simple version - the AI writer was unavailable this morning.)' : '';
  const subject = `${config.familyName || 'Family'} calendar - ${day.dateLabel}`;
  return {
    usedFallback,
    fallbackReason,
    emailSubject: subject,
    emailBody: `${body}${footer}`,
    telegramText: clip(`<b>${escapeHtml(subject)}</b>\n\n${escapeHtml(body)}${escapeHtml(footer)}`, 4000),
  };
}

// ---- n8n entry point

const config = $('Config').first().json;
const day = $('Merge & Dedupe Events').first().json;
const route = $('Build Digest Request').first().json.route;
const response = route === 'none' ? null : $input.first().json;
return [{ json: { chatId: config.telegramChatId, emailTo: config.digestEmailTo, ...composeDigest(day, response, config) } }];
